}
.jl-skel-brand {
  width: min(72%, 280px);
  height: 52px;
  margin: 0 auto;
}
.jl-skel-kicker {
  width: 92px;
  height: 13px;
  margin: 22px auto 0;
}
.jl-skel-line {
  width: 86%;
  height: 16px;
  margin: 18px auto 0;
}
.jl-skel-line.is-short {
  width: 58%;
  margin-top: 10px;
}
.jl-skel-chip {
  flex: none;
  width: 80px;
  height: 14px;
  margin: 19px 8px;
}
.jl-skel-sec {
  width: 52%;
  height: 38px;
}
.jl-skel-name {
  width: 56%;
  height: 22px;
}
.jl-skel-desc {
  width: 88%;
  height: 14px;
  margin-top: 10px;
}
o.jl-skel {
  display: block;
  border-radius: 2px;
  background: var(--jl-surface-2);
}
.jl-skel-shimmer {
  animation: jl-pulse 1.8s ease-in-out infinite;
}
@keyframes jl-pulse {
  50% {
    opacity: 0.55;
