.jl-skel-sec {
  width: 52%;
  height: 38px;
}
.jl-skel-name {
  width: 56%;
  height: 22px;
}
.jl-skel-desc {
  width: 88%;
  height: 14px;
  margin-top: 10px;
}
 .jl-skel {
